<details><summary>Sketch #2 - Full-Rx test sketch using existing startRecieveDutyCycleAuto method</summary>
<p>

```c++

/*
  RadioLib LR2021 Channel Activity Detection Example

  This example uses LR2021 to scan the current LoRa
  channel and detect ongoing LoRa transmissions.
  Unlike SX127x CAD, LR2021 can detect any part
  of LoRa transmission, not just the preamble.

  For default module settings, see the wiki page
  https://github.com/jgromes/RadioLib/wiki/Default-configuration#lr2021---lora-modem

  For full API reference, see the GitHub Pages
  https://jgromes.github.io/RadioLib/
*/

// include the library
#include <RadioLib.h>


// signal parameters
#define PREAMBLE_LEN 32
#define MIN_PREAMBLE 5

// LR2021 has the following connections:
#define NSS_PIN 3
#define IRQ_PIN 0
#define NRST_PIN 2
#define BUSY_PIN 1
LR2021 radio = new Module(3, 0, 2, 1);

// or detect the pinout automatically using RadioBoards
// https://github.com/radiolib-org/RadioBoards
/*
#define RADIO_BOARD_AUTO
#include <RadioBoards.h>
Radio radio = new RadioModule();
*/

String teststr = "a q p     w";

// flag to indicate that a packet was recieved
volatile bool receivedFlag = false;

// this function is called when a complete packet
// is received by the module
// IMPORTANT: this function MUST be 'void' type
//            and MUST NOT have any arguments!
#if defined(ESP8266) || defined(ESP32)
ICACHE_RAM_ATTR
#endif
void setFlag(void) {
  // something happened, set the flag
  receivedFlag = true;
}

void setup() {
  Serial.begin(9600);

  // LR2021 allows to use any DIO pin as the interrupt
  // as an example, we set DIO10 to be the IRQ
  // this has to be done prior to calling begin()!
  radio.irqDioNum = 8;
  radio.tcxoVoltage = 0;
  radio.fastCad = true;
  //radio.implicitHeader(teststr.length());

  // initialize LR2021 at 915 MHz
  Serial.print(F("[LR2021] Initializing ... "));
  ConfigLoRa_t config;
  config.frequency = 915;
  config.preambleLength = PREAMBLE_LEN;
  int state = radio.begin(config);
  if (state == RADIOLIB_ERR_NONE) {
    Serial.println(F("success!"));
  } else {
    Serial.print(F("failed, code "));
    Serial.println(state);
    while (true) { delay(10); }
  }

  // set the function that will be called
  // when a LoRa packet is recieved
  radio.setPacketReceivedAction(setFlag);

  // start scanning the channel
  Serial.print(F("[LR2021] Starting Periodic Receive ... "));
  state = radio.startReceiveDutyCycleAuto(PREAMBLE_LEN, MIN_PREAMBLE);
    if (state == RADIOLIB_ERR_NONE) {
    Serial.println(F("success!"));
  } else {
    Serial.print(F("failed, code "));
    Serial.println(state);
  }
}

// count number of recieved packets
int count = 0;

void loop() {

  //Serial.println("main loop entered");
  // check if the received flag is set
  if (receivedFlag) {
    receivedFlag = false;

    String str;
    int state = radio.readData(str);
    if (state == RADIOLIB_ERR_NONE) {
      Serial.print("[LR2021] Received Transmission #");
      Serial.println(count);
      // print data of the packet
      Serial.print(F("[LR2021] Data:\t\t"));
      Serial.println(str);
      count ++;
    } else if (state == RADIOLIB_ERR_CRC_MISMATCH) {
      // packet was received, but is malformed
      Serial.println(F("CRC error!"));
    } else {
      // some other error occurred
      Serial.print(F("failed, code "));
      Serial.println(state);
    }
    radio.startReceiveDutyCycleAuto(PREAMBLE_LEN, MIN_PREAMBLE);
  }
}

